@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;0,700;1,500;1,600&display=swap');
:root{color-scheme:dark;--cream:#f6ead8;--muted:#b7a99d;--gold:#e4b976;--wine:#7a315c;--panel:rgba(22,16,27,.88);--line:rgba(244,220,192,.15)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#100b17;color:var(--cream);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:radial-gradient(ellipse at 50% 35%,#332035 0%,#17101c 45%,#100b17 100%);isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(10,7,14,.48),transparent 25%,transparent 55%,rgba(9,7,13,.4) 100%),radial-gradient(ellipse at center,transparent 45%,rgba(7,5,10,.4) 100%);z-index:1}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:72px;padding:0 4.1%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.07);background:linear-gradient(180deg,rgba(15,9,18,.62),transparent)}.wordmark{text-decoration:none;color:#f2e7d8;font-size:12px;letter-spacing:.18em;font-weight:700;display:flex;align-items:center;gap:8px}.wordmark i{font-style:normal;color:#d9aa87;font-weight:500;letter-spacing:.11em}.mark{font-size:20px;color:#edc580}.top-right{display:flex;align-items:center;gap:20px}.age-pill{font-size:9px;letter-spacing:.16em;color:#d1beb0;border:1px solid rgba(236,213,183,.22);border-radius:20px;padding:7px 11px}.sound-toggle{border:0;background:transparent;color:#e5d6c6;font-size:14px;cursor:pointer;opacity:.8}.sound-toggle span{font-size:11px;margin-left:4px}.hud{position:absolute;z-index:3;top:92px;left:5%;right:5%;display:grid;grid-template-columns:1fr 1.15fr 1fr;align-items:start;pointer-events:none}.stat{display:flex;flex-direction:column;gap:5px}.stat-label,.eyebrow{font-size:9px;letter-spacing:.2em;color:#c7a781;font-weight:700}.stat strong{font-family:'Playfair Display',serif;font-size:27px;font-weight:500;letter-spacing:.03em}.stat-right{text-align:right;align-items:flex-end}.stat-right strong{font-family:'DM Sans',sans-serif;font-size:14px;color:#efc888;letter-spacing:.1em;margin-top:5px}.stat-right strong span{font-size:10px;color:#e3c9a7}.shift-center{display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:9px 13px;padding:2px 18px}.shift-name{font-size:9px;letter-spacing:.18em;color:#e7d4be;white-space:nowrap}.time-track{height:3px;flex:1;min-width:70px;max-width:180px;background:rgba(255,255,255,.19);border-radius:4px;overflow:hidden}.time-track div{height:100%;width:100%;background:linear-gradient(90deg,#d49d73,#f0ce91);transition:width .3s linear;border-radius:4px}.shift-center #timer{font-size:11px;color:#f2e0cc;font-variant-numeric:tabular-nums}.bottom-ui{position:absolute;z-index:4;bottom:0;left:0;right:0;padding:16px 5% max(14px,env(safe-area-inset-bottom));background:linear-gradient(180deg,rgba(13,9,18,0),rgba(13,9,18,.78) 12%,rgba(13,9,18,.93) 100%);transition:opacity .25s,transform .25s}.orders-head{display:flex;justify-content:space-between;align-items:end;margin:0 auto 12px;max-width:1240px}.orders-head h1{font-family:'Playfair Display',serif;font-size:22px;font-weight:500;margin:5px 0 0;letter-spacing:.01em}.order-count{font-size:10px;color:#d0c0b2;letter-spacing:.04em;display:flex;align-items:center;gap:8px;margin-bottom:4px}.pulse-dot{height:7px;width:7px;border-radius:50%;background:#dfad79;box-shadow:0 0 10px #dfad79;animation:pulse 1.7s infinite}@keyframes pulse{50%{opacity:.42;box-shadow:0 0 2px #dfad79}}.orders{max-width:1240px;margin:auto;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.order-card{position:relative;min-height:106px;display:grid;grid-template-columns:44px minmax(0,1fr) auto;align-items:center;gap:12px;padding:12px 14px;background:linear-gradient(120deg,rgba(39,28,40,.94),rgba(25,19,30,.94));border:1px solid rgba(244,220,192,.15);border-radius:8px;cursor:pointer;transition:transform .18s,border-color .2s,background .2s,opacity .2s;overflow:hidden;user-select:none}.order-card:hover{transform:translateY(-3px);border-color:rgba(235,192,132,.48)}.order-card.selected{border-color:#e4b976;background:linear-gradient(120deg,rgba(73,45,54,.96),rgba(37,25,35,.98));box-shadow:0 0 22px rgba(201,131,99,.13)}.order-card.served{opacity:.42;filter:saturate(.6);pointer-events:none}.order-card.missed{opacity:.32}.avatar{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;font-family:'Playfair Display',serif;font-size:18px;color:#f5e1c4;border:1px solid rgba(255,255,255,.18);box-shadow:inset 0 0 14px rgba(0,0,0,.3)}.guest-info{min-width:0}.guest-name{font-family:'Playfair Display',serif;font-size:15px;white-space:nowrap}.guest-line{margin-top:5px;color:#b9a99d;font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.drink-btn{min-width:103px;text-align:center;padding:9px 10px;border:1px solid rgba(236,193,133,.4);border-radius:5px;background:rgba(195,138,99,.1);color:#f2d5a9;font-size:10px;letter-spacing:.03em;cursor:pointer;transition:background .18s,border .18s,transform .18s}.drink-btn:hover{background:rgba(195,138,99,.28);border-color:#e8bc83;transform:scale(1.03)}.drink-btn:disabled{opacity:.6;cursor:default}.drink-emoji{font-size:14px;margin-right:4px}.order-card .seat-no{position:absolute;right:12px;top:7px;font-size:8px;letter-spacing:.13em;color:#938176}.mix-hint{max-width:1240px;margin:10px auto 0;color:#a89a91;font-size:9px;letter-spacing:.015em}.keycap{display:inline-grid;place-items:center;width:16px;height:17px;border-radius:3px;border:1px solid rgba(255,255,255,.2);color:#ecddc8;font-size:9px;margin-right:3px}.hint-divider{padding:0 6px;color:#d4a875}.hint-right{float:right;color:#81766f}.toast{position:absolute;z-index:6;left:50%;top:38%;transform:translate(-50%,8px);padding:10px 17px;border:1px solid rgba(233,194,139,.37);border-radius:6px;background:rgba(22,14,24,.93);font-family:'Playfair Display',serif;font-size:16px;color:#f1d29e;opacity:0;transition:.24s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-wrap{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:rgba(10,6,14,.43);backdrop-filter:blur(3px);transition:opacity .45s,visibility .45s}.modal-wrap.hidden{opacity:0;visibility:hidden;pointer-events:none}.modal-card{position:relative;z-index:2;width:min(430px,calc(100vw - 38px));padding:42px 44px 30px;text-align:center;border:1px solid rgba(238,199,153,.28);border-radius:5px;background:linear-gradient(145deg,rgba(35,24,36,.97),rgba(18,13,22,.98));box-shadow:0 25px 100px rgba(0,0,0,.55)}.intro-card{padding-top:43px}.mini-mark{font-size:9px;letter-spacing:.22em;color:#e2b783}.modal-card h2{font-family:'Playfair Display',serif;font-size:49px;line-height:.98;font-weight:500;margin:23px 0 15px}.modal-card h2 em{color:#e2b783;font-weight:500}.intro-copy{font-family:'Playfair Display',serif;font-size:17px;line-height:1.45;color:#f0dfcd;margin:0 auto 10px;max-width:320px}.intro-sub{font-size:12px;line-height:1.65;color:#b7a89c;margin:0 auto 25px;max-width:310px}.primary-btn{width:100%;padding:14px 18px;border:0;border-radius:3px;background:linear-gradient(100deg,#c9946f,#e1bc83);color:#241720;font-weight:700;font-size:10px;letter-spacing:.16em;cursor:pointer;box-shadow:0 6px 24px rgba(194,141,100,.18);transition:filter .2s,transform .2s}.primary-btn:hover{filter:brightness(1.12);transform:translateY(-2px)}.primary-btn span{font-size:17px;float:right;line-height:10px}.disclaimer{font-size:9px;line-height:1.7;color:#887b74;margin-top:17px}.modal-orbit{position:absolute;border:1px solid rgba(229,179,128,.15);border-radius:50%;pointer-events:none}.orbit-one{width:min(650px,90vw);height:min(650px,90vw)}.orbit-two{width:min(790px,105vw);height:min(790px,105vw);border-color:rgba(229,179,128,.09)}.result-card h2{font-size:36px;margin:20px 0 5px}.result-score{font-family:'Playfair Display',serif;color:#edc88f;font-size:48px;margin:0 0 6px}.result-stats{display:flex;justify-content:center;gap:45px;padding:14px 0 22px}.result-stats div{display:flex;flex-direction:column;gap:5px}.result-stats strong{font-family:'Playfair Display',serif;font-size:23px;font-weight:500}.result-stats span{font-size:8px;letter-spacing:.14em;color:#a8998d}.mobile-note{display:none}
@media(max-width:700px){.topbar{height:58px;padding:0 17px}.wordmark{font-size:10px;gap:5px}.wordmark i{font-size:9px}.top-right{gap:9px}.age-pill{font-size:7px;padding:6px 8px;letter-spacing:.1em}.sound-toggle span{display:none}.hud{top:72px;left:17px;right:17px;grid-template-columns:.75fr 1.5fr .75fr}.stat-label{font-size:7px;letter-spacing:.13em}.stat strong{font-size:21px}.stat-right strong{font-size:11px}.shift-center{padding:2px 8px;gap:6px}.shift-name{font-size:7px;letter-spacing:.12em}.time-track{min-width:35px}.shift-center #timer{font-size:9px}.bottom-ui{padding:12px 13px max(11px,env(safe-area-inset-bottom));}.orders-head{margin-bottom:8px}.orders-head h1{font-size:17px}.eyebrow{font-size:8px}.order-count{font-size:9px}.orders{gap:6px}.order-card{grid-template-columns:30px minmax(0,1fr);grid-template-rows:auto auto;gap:7px 8px;padding:9px 8px;min-height:100px;border-radius:6px;align-content:center}.avatar{width:30px;height:30px;font-size:14px}.guest-name{font-size:12px}.guest-line{font-size:8px;margin-top:3px}.drink-btn{grid-column:1/3;min-width:0;width:100%;padding:7px 4px;font-size:9px}.drink-emoji{font-size:11px}.order-card .seat-no{right:7px;top:4px;font-size:6px}.mix-hint{font-size:8px;margin-top:7px}.keycap{width:14px;height:15px;font-size:8px}.hint-right{display:none}.modal-card{padding:34px 25px 24px}.modal-card h2{font-size:44px}.intro-copy{font-size:16px}.toast{top:34%;font-size:14px}.mobile-note{position:absolute;z-index:4;display:block;left:0;right:0;bottom:164px;text-align:center;font-size:8px;color:rgba(235,220,203,.7);pointer-events:none;opacity:0;transition:opacity .5s}.mobile-note.show{opacity:1}}
@media(max-height:650px) and (min-width:701px){.bottom-ui{padding-bottom:10px}.orders-head h1{font-size:18px}.order-card{min-height:88px}.hud{top:80px}.topbar{height:60px}.modal-card{padding:30px 38px 23px}.modal-card h2{font-size:42px;margin:16px 0 12px}.intro-sub{margin-bottom:17px}}

