ba(76,49,53,.86);transform:translateY(-1px)}.recipe-btn .recipe-emoji{font-size:16px}.recipe-btn strong{display:block;font-family:'Playfair Display',serif;font-size:11px;font-weight:500;white-space:nowrap}.recipe-btn small{display:block;color:#9e8e83;font-size:8px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mix-hint{max-width:1240px;margin:7px auto 0;color:#a89a91;font-size:9px;letter-spacing:.015em}.keycap{display:inline-grid;place-items:center;width:16px;height:17px;border-radius:3px;border:1px solid rgba(255,255,255,.2);color:#ecddc8;font-size:9px;margin-right:3px}.hint-divider{padding:0 6px;color:#d4a875}.hint-right{float:right;color:#81766f}.toast{position:absolute;z-index:6;left:50%;top:38%;transform:translate(-50%,8px);padding:10px 17px;border:1px solid rgba(233,194,139,.37);border-radius:6px;background:rgba(22,14,24,.93);font-family:'Playfair Display',serif;font-size:16px;color:#f1d29e;opacity:0;transition:.24s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-wrap{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:rgba(10,6,14,.43);backdrop-filter:blur(3px);transition:opacity .45s,visibility .45s}.modal-wrap.hidden{opacity:0;visibility:hidden;pointer-events:none}.modal-card{position:relative;z-index:2;width:min(430px,calc(100vw - 38px));padding:42px 44px 30px;text-align:center;border:1px solid rgba(238,199,153,.28);border-radius:5px;background:linear-gradient(145deg,rgba(35,24,36,.97),rgba(18,13,22,.98));box-shadow:0 25px 100px rgba(0,0,0,.55)}.intro-card{padding-top:43px}.mini-mark{font-size:9px;letter-spacing:.22em;color:#e2b783}.modal-card h2{font-family:'Playfair Display',serif;font-size:49px;line-height:.98;font-weight:500;margin:23px 0 15px}.modal-card h2 em{color:#e2b783;font-weight:500}.intro-copy{font-family:'Playfair Display',serif;font-size:17px;line-height:1.45;color:#f0dfcd;margin:0 auto 10px;max-width:320px}.intro-sub{font-size:12px;line-height:1.65;color:#b7a89c;margin:0 auto 25px;max-width:310px}.primary-btn{width:100%;padding:14px 18px;border:0;border-radius:3px;background:linear-gradient(100deg,#c9946f,#e1bc83);color:#241720;font-weight:700;font-size:10px;letter-spacing:.16em;cursor:pointer;box-shadow:0 6px 24px rgba(194,141,100,.18);transition:filter .2s,transform .2s}.primary-btn:hover{filter:brightness(1.12);transform:translateY(-2px)}.primary-btn span{font-size:17px;float:right;line-height:10px}.disclaimer{font-size:9px;line-height:1.7;color:#887b74;margin-top:17px}.modal-orbit{position:absolute;border:1px solid rgba(229,179,128,.15);border-radius:50%;pointer-events:none}.orbit-one{width:min(650px,90vw);height:min(650px,90vw)}.orbit-two{width:min(790px,105vw);height:min(790px,105vw);border-color:rgba(229,179,128,.09)}.result-card h2{font-size:36px;margin:20px 0 5px}.result-score{font-family:'Playfair Display',serif;color:#edc88f;font-size:48px;margin:0 0 6px}.result-stats{display:flex;justify-content:center;gap:45px;padding:14px 0 22px}.result-stats div{display:flex;flex-direction:column;gap:5px}.result-stats strong{font-family:'Playfair Display',serif;font-size:23px;font-weight:500}.result-stats span{font-size:8px;letter-spacing:.14em;color:#a8998d}.mobile-note{display:none}
