import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $ = (id) => document.getElementById(id);
const canvas = $('scene');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#130d19');
scene.fog = new THREE.FogExp2('#130d19', 0.027);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 4.1, 11.6);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;
const clock = new THREE.Clock();
const mat = (color, roughness = 0.6, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const mats = {
  wall: mat('#271a2b'), floor: mat('#170f1b', .28, .3), dark: mat('#120d17', .3, .45), gold: mat('#bd8d57', .32, .68),
  goldLight: mat('#f0c888', .28, .55), velvet: mat('#4c203d', .88), wood: mat('#3c2631', .3, .22), shelf: mat('#392837', .28, .4),
  glass: new THREE.MeshPhysicalMaterial({ color: '#cf9b7f', roughness: .12, metalness: .12, transparent: true, opacity: .46, clearcoat: 1 }),
  red: mat('#a74e69', .23, .3), green: mat('#466d63', .25, .22), blue: mat('#48617f', .24, .26), cream: mat('#e0cba9', .68),
};
scene.add(new THREE.HemisphereLight('#e9ccdf', '#20131f', 1.55));
const ambient = new THREE.AmbientLight('#a9899f', .38); scene.add(ambient);
function addLight(color, intensity, position, distance = 12, size = 1) {
  const light = new THREE.PointLight(color, intensity, distance, 2);
  light.position.set(...position); scene.add(light);
  if (size) { const glow = new THREE.Mesh(new THREE.SphereGeometry(size, 16, 12), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .11 })); glow.position.copy(light.position); scene.add(glow); }
  return light;
}
addLight('#ed9c71', 95, [-4.3, 4.6, -2.4], 13, .33);
addLight('#9d6baa', 82, [4.1, 4.0, -3], 12, .32);
addLight('#f0c680', 72, [0, 5.2, 1], 10, .25);
const barLight = addLight('#d96291', 22, [0, 1.55, 1.0], 9, 0);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(200, 200), mats.floor); floor.rotation.x = -Math.PI / 2; floor.position.y = -.025; floor.receiveShadow = true; scene.add(floor);
const backWall = new THREE.Mesh(new THREE.BoxGeometry(15, 8, .35), mats.wall); backWall.position.set(0, 3.8, -5.3); backWall.receiveShadow = true; scene.add(backWall);
for (const x of [-7.3, 7.3]) { const side = new THREE.Mesh(new THREE.BoxGeometry(.35, 8, 11), mats.wall); side.position.set(x, 3.8, -.2); scene.add(side); }
// Deco wall panels and fine brass trim.
for (const x of [-6.4, -4.55, 4.55, 6.4]) {
  const panel = new THREE.Mesh(new THREE.BoxGeometry(1.38, 4.45, .05), mat('#311e32', .72)); panel.position.set(x, 3.3, -5.08); scene.add(panel);
  for (const dx of [-.61, .61]) { const trim = new THREE.Mesh(new THREE.BoxGeometry(.018, 4.12, .03), mats.gold); trim.position.set(x + dx, 3.3, -5.02); scene.add(trim); }
  const cap = new THREE.Mesh(new THREE.BoxGeometry(1.27, .025, .04), mats.gold); cap.position.set(x, 5.32, -5.01); scene.add(cap);
}
// Soft glowing art-deco arch behind the bar.
const archPoints = [];
for (let i = 0; i <= 36; i++) { const a = Math.PI * i / 36; archPoints.push(new THREE.Vector3(Math.cos(a) * 2.45, 2.45 + Math.sin(a) * 2.48, -5.02)); }
const archCurve = new THREE.CatmullRomCurve3(archPoints);
const arch = new THREE.Mesh(new THREE.TubeGeometry(archCurve, 80, .024, 8, false), new THREE.MeshBasicMaterial({ color: '#d58a92' })); scene.add(arch);
const signCanvas = document.createElement('canvas'); signCanvas.width = 1024; signCanvas.height = 256;
const signCtx = signCanvas.getContext('2d'); signCtx.textAlign = 'center'; signCtx.textBaseline = 'middle';
signCtx.shadowColor = '#f399b0'; signCtx.shadowBlur = 28; signCtx.fillStyle = '#f7d8c0'; signCtx.font = '600 104px Georgia'; signCtx.fillText('VELVET', 512, 122);
const signTexture = new THREE.CanvasTexture(signCanvas); signTexture.colorSpace = THREE.SRGBColorSpace;
const sign = new THREE.Mesh(new THREE.PlaneGeometry(2.85, .72), new THREE.MeshBasicMaterial({ map: signTexture, transparent: true, opacity: .9 })); sign.position.set(0, 4.14, -4.98); scene.add(sign);
// Long polished counter with brass inlay and underglow.
const barBase = new THREE.Mesh(new THREE.BoxGeometry(8.65, 1.06, 1.46), mats.wood); barBase.position.set(0, .54, .38); barBase.castShadow = true; barBase.receiveShadow = true; scene.add(barBase);
const inset = new THREE.Mesh(new THREE.BoxGeometry(8.2, .62, .025), mat('#291722', .4, .25)); inset.position.set(0, .55, 1.12); scene.add(inset);
const brassLine = new THREE.Mesh(new THREE.BoxGeometry(8.65, .025, .025), mats.goldLight); brassLine.position.set(0, .23, 1.125); scene.add(brassLine);
const counterTop = new THREE.Mesh(new THREE.BoxGeometry(9.05, .16, 1.82), mat('#251821', .18, .42)); counterTop.position.set(0, 1.13, .34); counterTop.castShadow = true; counterTop.receiveShadow = true; scene.add(counterTop);
for (const z of [-.52, 1.17]) { const edge = new THREE.Mesh(new THREE.BoxGeometry(9.02, .035, .035), mats.gold); edge.position.set(0, 1.05, z); scene.add(edge); }
const led = new THREE.Mesh(new THREE.BoxGeometry(8.5, .045, .045), new THREE.MeshBasicMaterial({ color: '#cc678e' })); led.position.set(0, .06, 1.13); scene.add(led);
// Back bar shelves, many colorful bottles, and suspended shelves.
for (const y of [1.73, 2.5]) {
  const shelf = new THREE.Mesh(new THREE.BoxGeometry(6.7, .11, .56), mats.shelf); shelf.position.set(0, y, -3.48); shelf.castShadow = true; scene.add(shelf);
  const lip = new THREE.Mesh(new THREE.BoxGeometry(6.7, .035, .025), mats.gold); lip.position.set(0, y - .045, -3.19); scene.add(lip);
  for (let i = 0; i < 13; i++) {
    const x = -3.0 + i * .5 + (y < 2 ? .16 : 0), h = .32 + ((i * 13 + Math.round(y * 10)) % 5) * .075;
    const colors = ['#b86855', '#638a78', '#d2a35f', '#71568f', '#477b8a'];
    const bottle = new THREE.Group(); bottle.position.set(x, y + .05, -3.55);
    const glass = new THREE.Mesh(new THREE.CylinderGeometry(.085, .105, h, 10), new THREE.MeshStandardMaterial({ color: colors[i % colors.length], roughness: .18, metalness: .1, transparent: true, opacity: .84 })); glass.position.y = h / 2; bottle.add(glass);
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(.035, .06, .13, 9), mats.gold); neck.position.y = h + .1; bottle.add(neck);
    const cork = new THREE.Mesh(new THREE.CylinderGeometry(.033, .033, .05, 8), mats.cream); cork.position.y = h + .19; bottle.add(cork); scene.add(bottle);
  }
}
// Pendant lamps over the service area.
const pendants = [];
for (const x of [-3.35, 0, 3.35]) {
  const cord = new THREE.Mesh(new THREE.CylinderGeometry(.012, .012, 1.15, 8), mats.gold); cord.position.set(x, 4.38, -1.72); scene.add(cord);
  const shade = new THREE.Mesh(new THREE.CylinderGeometry(.38, .2, .24, 24, 1, true), mat('#483040', .3, .4)); shade.position.set(x, 3.78, -1.72); scene.add(shade);
  const bulb = new THREE.Mesh(new THREE.SphereGeometry(.09, 16, 12), new THREE.MeshBasicMaterial({ color: '#f3c987' })); bulb.position.set(x, 3.62, -1.72); scene.add(bulb);
  const light = new THREE.PointLight('#e8ad7b', 14, 5, 2); light.position.set(x, 3.54, -1.65); scene.add(light); pendants.push(light);
}
// Three velvet bar stools.
for (const x of [-3, 0, 3]) {
  const post = new THREE.Mesh(new THREE.CylinderGeometry(.065, .085, .68, 16), mats.gold); post.position.set(x, .38, 1.8); scene.add(post);
  const foot = new THREE.Mesh(new THREE.CylinderGeometry(.38, .38, .06, 24), mats.dark); foot.position.set(x, .07, 1.8); scene.add(foot);
  const seat = new THREE.Mesh(new THREE.CylinderGeometry(.39, .42, .16, 24), mats.velvet); seat.position.set(x, .78, 1.8); seat.castShadow = true; scene.add(seat);
  const rim = new THREE.Mesh(new THREE.TorusGeometry(.38, .025, 8, 24), mats.gold); rim.rotation.x = Math.PI / 2; rim.position.set(x, .85, 1.8); scene.add(rim);
}
// Countertop accents: cocktail shaker, bar tools, citrus dish.
const shaker = new THREE.Mesh(new THREE.CylinderGeometry(.12, .17, .46, 16), new THREE.MeshStandardMaterial({ color: '#b8a9a8', metalness: .85, roughness: .2 })); shaker.position.set(-3.85, 1.42, .05); scene.add(shaker);
const shakerTop = new THREE.Mesh(new THREE.CylinderGeometry(.085, .12, .11, 16), mats.goldLight); shakerTop.position.set(-3.85, 1.7, .05); scene.add(shakerTop);
for (let i=0;i<3;i++){const citrus=new THREE.Mesh(new THREE.SphereGeometry(.11,12,10),mat(['#dcaa57','#9ea75a','#d47e59'][i],.38));citrus.position.set(3.55+i*.19,1.26,.23);citrus.scale.set(1,.48,1);scene.add(citrus);}
// Lighting sconces with warm pools on the back wall.
for(const x of [-5.4,5.4]){const back=new THREE.Mesh(new THREE.BoxGeometry(.22,.42,.12),mats.gold);back.position.set(x,3.55,-4.92);scene.add(back);const lamp=new THREE.Mesh(new THREE.SphereGeometry(.12,16,12),new THREE.MeshBasicMaterial({color:'#f5c58b'}));lamp.position.set(x,3.55,-4.78);scene.add(lamp);addLight('#e9a47e',14,[x,3.55,-4.35],4,0);}

const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
const guestGroups = [];
const guestData = [];
const guestPalette = [
  { name: 'Sloane', role: 'Art director · regular', color: '#9c557c', hair: '#241a2b', skin: '#c98c71', outfit: 'velvet' },
  { name: 'Rafael', role: 'Jazz pianist · first visit', color: '#52757a', hair: '#211a19', skin: '#a66c53', outfit: 'suit' },
  { name: 'Camille', role: 'Architect · night owl', color: '#80639b', hair: '#34202b', skin: '#e0b298', outfit: 'silk' },
  { name: 'Dante', role: 'Chef · just off shift', color: '#aa7150', hair: '#181419', skin: '#b87b62', outfit: 'suit' },
